SELECT c.id AS id, c.post_id AS postId, c.user_id AS userId, c.parent_id AS parentId, c.root_id AS rootId, c.content AS content, c.like_count AS likeCount, DATE_FORMAT(c.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, IFNULL(u.nickname, '') AS nickname FROM content_comment c INNER JOIN content_post p ON p.id = c.post_id LEFT JOIN sys_user u ON u.id = c.user_id WHERE (p.slug = #{slug} OR CONCAT('post-', p.id) = #{slug}) AND p.deleted = 0 AND c.status = 1 AND c.deleted = 0 AND c.parent_id = 0
AND c.id < #{cursor}
ORDER BY c.id DESC LIMIT #{size}

SELECT c.id AS id, c.post_id AS postId, c.user_id AS userId, c.parent_id AS parentId, c.root_id AS rootId, c.content AS content, c.like_count AS likeCount, DATE_FORMAT(c.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, IFNULL(u.nickname, '') AS nickname FROM content_comment c LEFT JOIN sys_user u ON u.id = c.user_id WHERE c.status = 1 AND c.deleted = 0 AND c.parent_id != 0 AND c.root_id IN
#{id}
ORDER BY c.create_time ASC, c.id ASC

